// Using a HEAD request to check file size before downloading

async function checkVideoSize() {
  const response = await fetch('https://api.com/massive-video.mp4', {
    method: 'HEAD' // Do NOT download the video!
  });

  // Read the headers the server sent back
  const sizeInBytes = response.headers.get('Content-Length');
  const sizeInGB = sizeInBytes / (1024 * 1024 * 1024);

  if (sizeInGB > 5) {
    alert("File is too large to download!");
  } else {
    // Safe to run the actual GET request now
  }
}
